def diff(x,y,path=''):
 out=[]
 if type(x)!=type(y):return [{'path':path,'before':x,'after':y}]
 if isinstance(x,dict):
  for k in sorted(set(x)|set(y)):
   if k not in x or k not in y:out.append({'path':path+'/'+k,'before':x.get(k),'after':y.get(k)})
   else:out+=diff(x[k],y[k],path+'/'+k)
 elif isinstance(x,list):
  if len(x)!=len(y):out.append({'path':path,'before':x,'after':y})
  else:
   for i,(l,r) in enumerate(zip(x,y)):out+=diff(l,r,path+'/'+str(i))
 elif x!=y:out.append({'path':path,'before':x,'after':y})
 return out
